\begin{align}
0&\longrightarrow N^*\xrightarrow{d}K\longrightarrow T\longrightarrow0,
\hypertarget{tag-003W}{}\label{cdp:A:filtration1}\\
0&\longrightarrow K\longrightarrow V\longrightarrow Q\longrightarrow0.
\hypertarget{tag-003X}{}\label{cdp:A:filtration2}
\end{align}
Let $\partial_A:H^0(S,Q\otimes A)\to H^1(S,K\otimes A)$ and $\delta_A:H^0(S,T\otimes A)\to H^1(S,N^*\otimes A)$ be their connecting maps. Then
\[
 H^0(S,V\otimes A)=0
 \quad\Longleftrightarrow\quad
 H^0(S,K\otimes A)=0\ \hbox{and}\ \partial_A\hbox{ is injective}.
\tag{A.1}\hypertarget{tag-003Y}{}\label{cdp:eq:A.1}
\]
Under the explicit hypotheses $H^0(S,N^*\otimes A)=0$ and $H^0(S,Q\otimes A)=0$, $H^0(S,V\otimes A)$ is canonically $\ker\delta_A$.
\end{proposition}


\begin{proof}
\begin{enumerate}[label=\arabic*.,leftmargin=*]
\item At a point of $S$, let $R=\mathcal O_{Y,s}$ and choose a reduced local defining equation $g$.
The generator $[g]$ of the conormal line identifies its stalk map with
\[
 R/(g)\longrightarrow (\Omega^1_R/g\Omega^1_R),
 \qquad \bar h\longmapsto h\,dg.
 \tag{W.145}\hypertarget{tag-03DW}{}\label{wbII:eq:CN:2.2}
\]
The quotient $R/(g)$ is reduced, and its total quotient ring is the product
of the fraction fields of its irreducible components. At the generic point
of every component, $S$ is smooth and $dg$ is nonzero. Thus a class
$\bar h$ in the kernel of \eqref{wbII:eq:CN:2.2} vanishes in each of those
fields. The reduced ring $R/(g)$ injects into their product, so
$\bar h=0$. This proves injectivity in the usual right-exact conormal sequence. Taking the inverse image of $T\subset\Omega_S^1$ gives \eqref{cdp:A:filtration1} and \eqref{cdp:A:filtration2}. Tensoring by $A$ is exact because $A$ is locally free. The cohomology sequence of \eqref{cdp:A:filtration2} identifies the image of $H^0(VA)$ in $H^0(QA)$ with $\ker\partial_A$ and its kernel with $H^0(KA)$, proving \eqref{cdp:eq:A.1}. When $H^0(QA)=0$, it identifies $H^0(VA)$ with $H^0(KA)$. The first sequence then identifies this group with $\ker\delta_A$ when $H^0(N^*A)=0$.

\end{enumerate}
\end{proof}

