\begin{equation}\label{eq:II:quasibundle-canonical}
 K_P\simeq q^*K_B\otimes\OO_P\Bigl(\sum_b(m_b-1)J_b\Bigr),
 \qquad q_*K_P\simeq K_B.
\end{equation}
If $S=P\cup_iH_i$ is the full reduced fibre of a proper
